using Mono.Cecil;
using Mono.Cecil.Cil;
using System.Text.Json;
namespace WinrtSecondPass;
static class DynamicAudit
{
 static IEnumerable<TypeDefinition> Types(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in Types(n))yield return x;}
 public static void Run(string before,string after,string shared,string output){using var a=AssemblyDefinition.ReadAssembly(Path.Combine(before,"Microsoft.Windows.SDK.NET.dll"));using var b=AssemblyDefinition.ReadAssembly(Path.Combine(after,"Microsoft.Windows.SDK.NET.dll"));var old=a.MainModule.Types.SelectMany(Types).Single(t=>t.FullName=="<PrivateImplementationDetails>");var nt=b.MainModule.Types.SelectMany(Types).Single(t=>t.FullName==old.FullName);var removed=old.Fields.Where(f=>!nt.Fields.Any(x=>x.FullName==f.FullName)).ToArray();var names=removed.Select(f=>f.Name).ToHashSet();var strings=new List<object>();var fieldLookups=new List<object>();var relevant=new List<object>();var models=new List<string>();int managed=0;bool allHex16=removed.All(f=>f.InitialValue.Length==16&&f.Name.Equals(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(f.InitialValue)),StringComparison.Ordinal));
 foreach(var file in Directory.GetFiles(before,"*.dll",SearchOption.AllDirectories).Concat(Directory.GetFiles(shared,"*.dll",SearchOption.AllDirectories)).Order()){AssemblyDefinition x;try{x=AssemblyDefinition.ReadAssembly(file);}catch(BadImageFormatException){continue;}using(x){managed++;var types=x.MainModule.Types.SelectMany(Types).ToArray();if(x.Name.Name=="HandheldCompanion"){foreach(var t in types.Where(t=>t.IsClass&&!t.IsAbstract&&t.FullName.StartsWith("HandheldCompanion.Devices."))){var current=t;var visited=new HashSet<string>();while(current.BaseType!=null&&visited.Add(current.FullName)){if(current.BaseType.FullName=="HandheldCompanion.Devices.IDevice"){models.Add(t.FullName);break;}current=types.FirstOrDefault(o=>o.FullName==current.BaseType.FullName)!;if(current==null)break;}}}
 foreach(var t in types)foreach(var m in t.Methods.Where(m=>m.HasBody)){foreach(var i in m.Body.Instructions){if(i.OpCode.Code==Code.Ldstr&&i.Operand is string s&&(names.Contains(s)||s.Contains("<PrivateImplementationDetails>",StringComparison.Ordinal)))strings.Add(new{source=x.Name.Name,owner=m.FullName,offset=i.Offset,value=s});if(i.Operand is MethodReference mr&&mr.DeclaringType.FullName=="System.Type"&&mr.Name is "GetField" or "GetFields"){var idx=m.Body.Instructions.IndexOf(i);var context=m.Body.Instructions.Skip(Math.Max(0,idx-7)).Take(8).Select(v=>v.OpCode+" "+(v.Operand?.ToString()??"")).ToArray();fieldLookups.Add(new{source=x.Name.Name,owner=m.FullName,offset=i.Offset,call=mr.FullName,context});if(x.Name.Name=="WinRT.Runtime")relevant.Add(new{owner=m.FullName,call=mr.FullName,literalFieldNames=m.Body.Instructions.Where(v=>v.OpCode.Code==Code.Ldstr).Select(v=>(string)v.Operand).Distinct().ToArray()});}}}
 }}
 File.WriteAllText(output,JsonSerializer.Serialize(new{managedConsumerCount=managed,removedDataFields=removed.Length,allRemovedFieldsAre16ByteCompilerHashNamedRvaConstants=allHex16,removedFieldOrContainerLiteralMentions=strings,allReflectionFieldLookupSites=fieldLookups,winrtRuntimeReflectionFieldLookupSites=relevant,hcConcreteDeviceDerivedTypes=models.Order().ToArray(),hcConcreteDeviceDerivedTypeCount=models.Count,findings=new[]{"All SDK type/member/attribute roots are preserved except nonpublic compiler RVA fields.","All original retained IL including ldtoken field operands and all retained field RVA bytes are compared, so every generated IID/vtable constructor retains its data.","WinRT.Runtime remains byte-identical; helper, activation, generic and reflection code is unchanged.","Compiler container is nonpublic/sealed/CompilerGenerated with no constructors, methods, interfaces or projected WinRT metadata.","No immutable consumer literal names the compiler container or any removed compiler hash field.","Arbitrary external reflection into implementation-only compiler RVA storage is outside the current consumer/WinRT contract; no static-absence-only approval is asserted."}},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"DYNAMIC DATA {removed.Length} hash-named GUID blobs; literals {strings.Count}; models {models.Count}; consumers {managed}");}
}


